  const finishGame = () => {
    const result = getResult()
    if (result?.correct) {
      setWins(prev => prev + 1)
    } else {
      setLosses(prev => prev + 1)
    }

    setTimeout(() => {
      setGameState('waiting')
      setPrediction(null)
      setStartPrice(null)
      setTimeLeft(0)
    }, 3000)
  }

