* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: #333;
}

.app {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.game-container {
  background: white;
  border-radius: 20px;
  padding: 40px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
  text-align: center;
  max-width: 500px;
  width: 100%;
}

h1 {
  font-size: 2.5rem;
  margin-bottom: 10px;
  color: #2d3748;
}

.subtitle {
  color: #718096;
  font-size: 1.1rem;
  margin-bottom: 30px;
}

.price-display {
  background: #f7fafc;
  border-radius: 15px;
  padding: 25px;
  margin-bottom: 30px;
  border: 2px solid #e2e8f0;
}

.current-price {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.label {
  font-size: 0.9rem;
  color: #718096;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.price {
  font-size: 2.2rem;
  font-weight: bold;
  color: #2d3748;
  font-family: 'Monaco', 'Menlo', monospace;
}

.score-board {
  display: flex;
  justify-content: space-around;
  margin-bottom: 30px;
  background: #f8f9fa;
  border-radius: 15px;
  padding: 20px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.stat-value {
  font-size: 1.8rem;
  font-weight: bold;
  color: #2d3748;
}

.stat-label {
  font-size: 0.9rem;
  color: #718096;
  font-weight: 500;
}

.game-controls p {
  font-size: 1.2rem;
  margin-bottom: 20px;
  color: #4a5568;
}

.prediction-buttons {
  display: flex;
  gap: 20px;
  justify-content: center;
}

.predict-btn {
  background: linear-gradient(135deg, #48bb78, #38a169);
  color: white;
  border: none;
  padding: 18px 35px;
  border-radius: 50px;
  font-size: 1.3rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(72, 187, 120, 0.3);
  min-width: 120px;
}

.predict-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(72, 187, 120, 0.4);
}

.predict-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.predict-btn.down {
  background: linear-gradient(135deg, #f56565, #e53e3e);
  box-shadow: 0 4px 15px rgba(245, 101, 101, 0.3);
}

.predict-btn.down:hover:not(:disabled) {
  box-shadow: 0 8px 25px rgba(245, 101, 101, 0.4);
}

.active-game {
  display: flex;
  flex-direction: column;
  gap: 25px;
}

.timer {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  padding: 30px;
  border-radius: 20px;
  box-shadow: 0 8px 25px rgba(102, 126, 234, 0.3);
}

.time-left {
  font-size: 3rem;
  font-weight: bold;
  display: block;
}

.timer-label {
  font-size: 1rem;
  opacity: 0.9;
}

.prediction-info {
  background: #f8f9fa;
  padding: 20px;
  border-radius: 15px;
}

.prediction-info p {
  margin: 8px 0;
  font-size: 1.1rem;
}

.prediction-info strong.up {
  color: #38a169;
}

.prediction-info strong.down {
  color: #e53e3e;
}

.result {
  padding: 30px;
  border-radius: 20px;
  animation: slideIn 0.5s ease-out;
}

.result.win {
  background: linear-gradient(135deg, #48bb78, #38a169);
  color: white;
}

.result.lose {
  background: linear-gradient(135deg, #f56565, #e53e3e);
  color: white;
}

.result-icon {
  font-size: 4rem;
  margin-bottom: 15px;
}

.result h2 {
  font-size: 2rem;
  margin-bottom: 20px;
}

.result-details p {
  margin: 8px 0;
  font-size: 1.1rem;
  opacity: 0.95;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 600px) {
  .game-container {
    padding: 25px;
    margin: 10px;
  }

  h1 {
    font-size: 2rem;
  }

  .prediction-buttons {
    flex-direction: column;
    align-items: center;
  }

  .predict-btn {
    width: 200px;
  }

  .score-board {
    flex-direction: column;
    gap: 15px;
  }
}

