{"path": "src/App.jsx", "content": "import { useState, useEffect, useCallback } from 'react'
import './App.css'

// Helper function to call Pyth MCP Server
async function pythMCP(toolName, args) {
  // Step 1: Initialize session
  const init = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 0, method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'ouroboros-app', version: '1.0' } }
    })
  });
  await init.json();

  // Step 2: Call the tool  
  const res = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'tools/call',
      params: { name: toolName, arguments: args }
    })
  });
  const data = await res.json();
  const text = data.result?.content?.[0]?.text || '';
  return JSON.parse(text);
}

function App() {
  const [currentPrice, setCurrentPrice] = useState(null)
  const [startPrice, setStartPrice] = useState(null)
  const [prediction, setPrediction] = useState(null)
  const [timeLeft, setTimeLeft] = useState(0)
  const [gameState, setGameState] = useState('waiting') // waiting, active, finished
  const [wins, setWins] = useState(0)
  const [losses, setLosses] = useState(0)
  const [loading, setLoading] = useState(false)

  // Fetch current BTC price
  const fetchPrice = useCallback(async () => {
    try {
      const data = await pythMCP('get_historical_price', { 
        symbols: ['Crypto.BTC/USD'], 
        timestamp: Math.floor(Date.now() / 1000)
      })
      if (data.prices && data.prices['Crypto.BTC/USD']) {
        const priceData = data.prices['Crypto.BTC/USD']
        const price = parseFloat(priceData.price) * Math.pow(10, priceData.expo)
        setCurrentPrice(price)
        return price
      }
    } catch (error) {
      console.error('Error fetching price:', error)
    }
    return null
  }, [])

  // Start a new prediction round
  const startPrediction = async (predictionType) => {
    setLoading(true)
    const price = await fetchPrice()
    if (price) {
      setStartPrice(price)
      setPrediction(predictionType)
      setTimeLeft(60)
      setGameState('active')
    }
    setLoading(false)
  }

  // Timer countdown
  useEffect(() => {
    let interval
    if (gameState === 'active' && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft(prev => prev - 1)
      }, 1000)
    } else if (timeLeft === 0 && gameState === 'active') {
      setGameState('finished')
    }
    return () => clearInterval(interval)
  }, [gameState, timeLeft])

  // Fetch price every 2 seconds during active game
  useEffect(() => {
    let interval
    if (gameState === 'active') {
      interval = setInterval(fetchPrice, 2000)
    }
    return () => clearInterval(interval)
  }, [gameState, fetchPrice])

  // Calculate result when game finishes
  const getResult = () => {
    if (!startPrice || !currentPrice || !prediction) return null

    const priceChange = currentPrice - startPrice
    const actualDirection = priceChange > 0 ? 'up' : 'down'
    const correct = prediction === actualDirection

    return {
      correct,
      priceChange: priceChange.toFixed(2),
      percentage: ((priceChange / startPrice) * 100).toFixed(3)
    }
  }

  // Handle game completion
  const finishGame = () => {
    const result = getResult()
    if (result?.correct) {
      setWins(prev => prev + 1)
    } else {
      setLosses(prev => prev + 1)
    }

    setTimeout(() => {
      setGameState('waiting')
      setPrediction(null)
      setStartPrice(null)
      setTimeLeft(0)
    }, 3000)
  }

  useEffect(() => {
    if (gameState === 'finished') {
      finishGame()
    }
  }, [gameState])

  // Initial price fetch
  useEffect(() => {
    fetchPrice()
  }, [fetchPrice])

  const result = gameState === 'finished' ? getResult() : null
  const totalGames = wins + losses
  const winRate = totalGames > 0 ? ((wins / totalGames) * 100).toFixed(1) : 0

  return (
    <div className="app">
      <div className="game-container">
        <h1>🚀 BTC Price Prediction</h1>
        <p className="subtitle">Will Bitcoin go UP or DOWN in the next minute?</p>

        <div className="price-display">
          <div className="current-price">
            <span className="label">Current BTC Price</span>
            <span className="price">
              ${currentPrice ? currentPrice.toLocaleString('en-US', { 
                minimumFractionDigits: 2, 
                maximumFractionDigits: 2 
              }) : '---'}
            </span>
          </div>
        </div>

        <div className="score-board">
          <div className="stat">
            <span className="stat-value">{wins}</span>
            <span className="stat-label">Wins</span>
          </div>
          <div className="stat">
            <span className="stat-value">{losses}</span>
            <span className="stat-label">Losses</span>
          </div>
          <div className="stat">
            <span className="stat-value">{winRate}%</span>
            <span className="stat-label">Accuracy</span>
          </div>
        </div>

        {gameState === 'waiting' && (
          <div className="game-controls">
            <p>Make your prediction:</p>
            <div className="prediction-buttons">
              <button 
                className="predict-btn up" 
                onClick={() => startPrediction('up')}
                disabled={loading}
              >
                📈 UP
              </button>
              <button 
                className="predict-btn down" 
                onClick={() => startPrediction('down')}
                disabled={loading}
              >
                📉 DOWN
              </button>
            </div>
          </div>
        )}

        {gameState === 'active' && (
          <div className="active-game">
            <div className="timer">
              <span className="time-left">{timeLeft}s</span>
              <span className="timer-label">remaining</span>
            </div>

            <div className="prediction-info">
              <p>You predicted: <strong className={prediction}>{prediction.toUpperCase()}</strong></p>
              <p>Starting price: <strong>${startPrice?.toLocaleString('en-US', { 
                minimumFractionDigits: 2, 
                maximumFractionDigits: 2 
              })}</strong></p>
            </div>
          </div>
        )}

        {gameState === 'finished' && result && (
          <div className={`result ${result.correct ? 'win' : 'lose'}`}>
            <div className="result-icon">
              {result.correct ? '🎉' : '😞'}
            </div>
            <h2>{result.correct ? 'You Won!' : 'You Lost!'}</h2>
            <div className="result-details">
              <p>Price moved {result.priceChange > 0 ? 'UP' : 'DOWN'}</p>
              <p>Change: ${result.priceChange} ({result.percentage}%)</p>
              <p>From ${startPrice?.toLocaleString('en-US', { 
                minimumFractionDigits: 2, 
                maximumFractionDigits: 2 
              })} to ${currentPrice?.toLocaleString('en-US', { 
                minimumFractionDigits: 2, 
                maximumFractionDigits: 2 
              })}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default App"}

